export function getOfflineWorldLakesGeoJSON(): any {
  if (!parsedLakesFC) {
    parsedLakesFC = JSON.parse(OFFLINE_WORLD_LAKES_RAW);
  }
  return parsedLakesFC;
}

export function getOfflineWorldRiversGeoJSON(): any {
  if (!parsedRiversFC) {
    parsedRiversFC = JSON.parse(OFFLINE_WORLD_RIVERS_RAW);
  }
  return parsedRiversFC;
}

export function getOfflineWorldCitiesGeoJSON(): any {
  if (!parsedCitiesFC) {
    parsedCitiesFC = JSON.parse(OFFLINE_WORLD_CITIES_RAW);
  }
  return parsedCitiesFC;
}

export function getOfflineCitiesList(): OfflineCityEntry[] {
  if (!parsedCityList) {
    const fc = getOfflineWorldCitiesGeoJSON();
    parsedCityList = (fc.features || []).map((f: any) => ({
      n: f.properties.n,
      c: f.properties.c,
      s: f.properties.s,
      p: f.properties.p,
      lon: f.geometry.coordinates[0],
      lat: f.geometry.coordinates[1],
    }));
  }
  return parsedCityList!;
}

export function getOfflineRiverLabelsList(): OfflineRiverLabelEntry[] {
  if (!parsedRiverLabels) {
    parsedRiverLabels = JSON.parse(OFFLINE_RIVER_LABELS_RAW);
  }
  return parsedRiverLabels!;
}

export function getOfflineGraticuleGeoJSON(): any {
  if (parsedGraticuleFC) {
    return parsedGraticuleFC;
  }
  const features: any[] = [];
  // Meridians every 2 degrees (-180 to 180)
  for (let lon = -180; lon <= 180; lon += 2) {
    const isMajor = lon % 10 === 0;
    const coords: [number, number][] = [];
    for (let lat = -84; lat <= 84; lat += 4) {
      coords.push([lon, lat]);
    }
    features.push({
      type: "Feature",
      properties: { major: isMajor ? 1 : 0 },
      geometry: { type: "LineString", coordinates: coords },
    });
  }
  // Parallels every 2 degrees (-80 to 80)
  for (let lat = -80; lat <= 80; lat += 2) {
    const isMajor = lat % 10 === 0;
    const coords: [number, number][] = [];
    for (let lon = -180; lon <= 180; lon += 6) {
      coords.push([lon, lat]);
    }
    features.push({
      type: "Feature",
      properties: { major: isMajor ? 1 : 0 },
      geometry: { type: "LineString", coordinates: coords },
    });
  }
  parsedGraticuleFC = { type: "FeatureCollection", features };
  return parsedGraticuleFC;
}

export function buildOfflineVectorStyle(dark: boolean = false): maplibregl.StyleSpecification {
  const oceanColor = dark ? "#0b192c" : "#cbe0ee";
  const lakeFillColor = dark ? "#0e223b" : "#bed9ec";
  const lakeLineColor = dark ? "#1e4976" : "#78a9c9";
  const riverColor = dark ? "#38bdf8" : "#4a90c2";
  const graticuleMajorColor = dark ? "#1e3a5f" : "#93b8d1";
  const graticuleMinorColor = dark ? "#162a45" : "#b0cfe3";
  const borderColor = dark ? "#475569" : "#758ca3";
  const cityFillColor = dark ? "#cbd5e1" : "#334155";
  const cityStrokeColor = dark ? "#0f172a" : "#ffffff";
  const capitalOuterColor = dark ? "#f8fafc" : "#ffffff";
  const capitalRingColor = dark ? "#f87171" : "#b91c1c";
  const capitalCoreColor = dark ? "#ef4444" : "#dc2626";

  const landFillExpr: any = dark
    ? [
        "match",
        ["get", "c"],
        1, "#1e293b",
        2, "#1a2436",
        3, "#222e42",
        4, "#1c2739",
        5, "#243146",
        6, "#192231",
        "#1e293b",
      ]
    : [
        "match",
        ["get", "c"],
        1, "#f4f1ea",
        2, "#efeadd",
        3, "#f7f4ee",
        4, "#ece7da",
        5, "#f1ede4",
        6, "#eae4d7",
        "#f3f0e8",
      ];

  return {
    version: 8,
    name: dark ? "Gong Offline Vector World (Dark)" : "Gong Offline Vector World",
    sources: {
      "gong-offline-world-src": {
        type: "geojson",
        data: getOfflineWorldCountriesGeoJSON(),
      },
      "gong-offline-lakes-src": {
        type: "geojson",
        data: getOfflineWorldLakesGeoJSON(),
      },
      "gong-offline-rivers-src": {
        type: "geojson",
        data: getOfflineWorldRiversGeoJSON(),
      },
      "gong-offline-cities-src": {
        type: "geojson",
        data: getOfflineWorldCitiesGeoJSON(),
      },
      "gong-offline-graticule-src": {
        type: "geojson",
        data: getOfflineGraticuleGeoJSON(),
      },
    },
    layers: [
      {
        id: "gong-world-ocean",
        type: "background",
        paint: {
          "background-color": oceanColor,
        },
      },
      {
        id: "gong-world-graticule-minor",
        type: "line",
        source: "gong-offline-graticule-src",
        minzoom: 3.5,
        filter: ["==", ["get", "major"], 0],
        paint: {
          "line-color": graticuleMinorColor,
          "line-width": 0.6,
          "line-opacity": 0.45,
          "line-dasharray": [3, 3],
        },
      },
      {
        id: "gong-world-graticule-major",
        type: "line",
        source: "gong-offline-graticule-src",
        filter: ["==", ["get", "major"], 1],
        paint: {
          "line-color": graticuleMajorColor,
          "line-width": 0.9,
          "line-opacity": 0.6,
        },
      },
      {
        id: "gong-world-land-fill",
        type: "fill",
        source: "gong-offline-world-src",
        paint: {
          "fill-color": landFillExpr,
          "fill-opacity": 1.0,
        },
      },
      {
        id: "gong-world-lakes-fill",
        type: "fill",
        source: "gong-offline-lakes-src",
        paint: {
          "fill-color": lakeFillColor,
          "fill-opacity": 1.0,
        },
      },
      {
        id: "gong-world-lakes-outline",
        type: "line",
        source: "gong-offline-lakes-src",
        paint: {
          "line-color": lakeLineColor,
          "line-width": 0.7,
          "line-opacity": 0.85,
        },
      },
      {
        id: "gong-world-rivers-line",
        type: "line",
        source: "gong-offline-rivers-src",
        minzoom: 2.5,
        filter: [
          "<=",
          ["get", "s"],
          [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.5, 4,
            4.0, 6,
            5.0, 8,
            6.0, 10,
          ],
        ],
        layout: {
          "line-cap": "round",
          "line-join": "round",
        },
        paint: {
          "line-color": riverColor,
          "line-opacity": [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.5, 0.55,
            5.0, 0.8,
            8.0, 0.92,
          ],
          "line-width": [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.5, ["case", ["<=", ["get", "s"], 3], 1.1, 0.7],
            5.0, ["case", ["<=", ["get", "s"], 3], 1.8, ["<=", ["get", "s"], 6], 1.3, 0.9],
            8.0, ["case", ["<=", ["get", "s"], 3], 2.8, ["<=", ["get", "s"], 6], 2.0, 1.4],
          ],
        },
      },
      {
        id: "gong-world-country-borders",
        type: "line",
        source: "gong-offline-world-src",
        paint: {
          "line-color": borderColor,
          "line-width": [
            "interpolate",
            ["linear"],
            ["zoom"],
            1, 0.5,
            4, 0.9,
            8, 1.5,
          ],
          "line-opacity": 0.85,
        },
      },
      {
        id: "gong-world-cities-circle",
        type: "circle",
        source: "gong-offline-cities-src",
        minzoom: 2.5,
        filter: [
          "all",
          ["==", ["get", "c"], 0],
          [
            "<=",
            ["get", "s"],
            [
              "interpolate",
              ["linear"],
              ["zoom"],
              2.5, 1,
              4.0, 3,
              5.0, 5,
              6.5, 8,
              8.0, 10,
            ],
          ],
        ],
        paint: {
          "circle-radius": [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.5, 2.0,
            5.0, 3.0,
            8.0, 4.2,
          ],
          "circle-color": cityFillColor,
          "circle-stroke-color": cityStrokeColor,
          "circle-stroke-width": 1.0,
          "circle-opacity": 0.88,
        },
      },
      {
        id: "gong-world-capitals-outer",
        type: "circle",
        source: "gong-offline-cities-src",
        minzoom: 2.0,
        filter: ["==", ["get", "c"], 1],
        paint: {
          "circle-radius": [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.0, 3.5,
            5.0, 4.8,
            8.0, 6.0,
          ],
          "circle-color": capitalOuterColor,
          "circle-stroke-color": capitalRingColor,
          "circle-stroke-width": 1.5,
          "circle-opacity": 0.95,
        },
      },
      {
        id: "gong-world-capitals-inner",
        type: "circle",
        source: "gong-offline-cities-src",
        minzoom: 2.0,
        filter: ["==", ["get", "c"], 1],
        paint: {
          "circle-radius": [
            "interpolate",
            ["linear"],
            ["zoom"],
            2.0, 1.6,
            5.0, 2.2,
            8.0, 2.8,
          ],
          "circle-color": capitalCoreColor,
          "circle-opacity": 1.0,
        },
      },
    ],
  };
}
